"""Render the v2 report from completed, preserved analyses; never invoke models."""
import json
from pathlib import Path
from pypdf import PdfReader
from report_utils import render_report

ROOT=Path(__file__).resolve().parents[1]


def main():
    summary=json.loads((ROOT/'artifacts/analysis/deliberation_summary_2026-11-25.json').read_text(encoding='utf-8'))
    studies=summary['studies']
    bonsai=next(x for x in studies if x['backend']=='bonsai' and x['runs'])
    luna=next(x for x in studies if x['backend']=='codex' and x['runs'])
    diag_b=next(x for x in studies if x['backend']=='bonsai' and not x['runs'])['diagnostics']
    diag_l=next(x for x in studies if x['backend']=='codex' and not x['runs'])['diagnostics']
    full_b=next(x for x in bonsai['runs'] if x['config']['name']=='rotating_text')
    full_l=next(x for x in luna['runs'] if x['config']['name']=='rotating_text')
    all_usage=json.loads((ROOT/'artifacts/analysis/deliberation_usage_2026-11-25.json').read_text(encoding='utf-8'))
    pages=[]
    def page(title):s=[('h1',title)];pages.append(s);return s
    def p(s,text):s.append(('p',text))
    def h(s,text):s.append(('h2',text))
    def table(s,headers,rows,widths):s.append(('table',(headers,rows,widths)))
    s=page('Новые собеседники и проверяемые факты')
    p(s,'Продолжение лабораторного прототипа. 25.11.2026. В первом сценарии 88,3% поздних шагов в базовых условиях с воздействием не меняли позицию. Проверяем, помогает ли более конкретная постановка, и подключаем GPT-Luna через Codex, как предложено в задании.')
    h(s,'Что изменилось')
    p(s,'Шесть подробных профилей с потребностями и бюджетом. Начальные позиции формирует модель, без навязанного initial_opinion. Пять раундов попарных встреч: каждый обсуждает с каждым другим ровно один раз. Собственные аргументы возвращаются в контекст, чужие численные позиции в основном условии скрыты.')
    table(s,['Раунд','Новое сведение'],[
        ['0','Цифровая стоимость 120, печатная 80; цифровой вариант без офлайн-загрузки'],
        ['1','Появляется офлайн-загрузка цифровых книг'],['2','Фасад перекрашен; условия выбора не меняются'],
        ['3','Бюллетень сообщает цифровую стоимость 40'],['4','Исправление: правильная цифровая стоимость 140, прежние 40 отозваны'],
        ['5','Появляются обучение и выдача устройств; стоимость не меняется']],[.12,.88])
    p(s,'Встречи синхронные: участник видит последнюю публичную реплику нового собеседника из предыдущего раунда, затем формирует свою. Это один обмен за раунд, без нескольких реплик туда-обратно. Все получают одни и те же новые официальные сведения.')
    p(s,'Технические проверки: 36 тестов. Заглушка прошла весь план 204 вызова без сети. В реальной основной серии bonsai выполнено 204 вызова; Luna через Codex - 60. Дополнительные smoke, проба интеграции и исправленная диагностика сохранены отдельно.')

    s=page('Факты, позиции и сравнение маршрутов')
    table(s,['Проверка','bonsai / API','GPT-6-Luna / Codex'],[
        ['Исправленная одношаговая диагностика',f"{diag_b['beliefs_correct']}/{diag_b['cases']} верных наборов фактов",f"{diag_l['beliefs_correct']}/{diag_l['cases']} верных наборов фактов"],
        ['Основной сценарий, все ответы',f"{full_b['beliefs_correct']}/{full_b['beliefs_total']} верных наборов фактов",f"{full_l['beliefs_correct']}/{full_l['beliefs_total']} верных наборов фактов"],
        ['Неизменные позиции после первого раунда',f"{full_b['late_unchanged_opinions']}/{full_b['late_agent_steps']}",f"{full_l['late_unchanged_opinions']}/{full_l['late_agent_steps']}"],
        ['Дословные повторы своего предыдущего сообщения',str(full_b['verbatim_own_repeats']),str(full_l['verbatim_own_repeats'])],
        ['Совпадения с доставленным сообщением партнёра',str(full_b['verbatim_peer_matches']),str(full_l['verbatim_peer_matches'])],
        ['Ответы длиннее запрошенного, основной сценарий',str(full_b['answers_exceeding_requested_length']),str(full_l['answers_exceeding_requested_length'])]
    ],[.46,.27,.27])
    p(s,'Проверяются только три явных факта: наличие офлайн-доступа, цифровая и печатная стоимость. Правильный набор этих полей не доказывает логическую связность текста, уважение бюджета или полноценную социальную симуляцию.')
    h(s,'Изменения позиции по раундам')
    table(s,['Переход','bonsai','Luna'],[[f'{t-1} -> {t}',f"{full_b['rounds'][t]['mean_abs_step']:.4f}",f"{full_l['rounds'][t]['mean_abs_step']:.4f}"] for t in range(1,6)],[.34,.33,.33])
    p(s,'Это описательное сравнение двух конфигураций. У Codex собственные системные инструкции и ограничения вывода, температуру не удалось выровнять. Шкала самозаявленных позиций не откалибрована между моделями. Нельзя объявлять модель лучше только по большему сдвигу или меньшему числу повторов.')

    s=page('Что меняют память, профили и смена пар')
    table(s,['Условие bonsai','Разных пар','Поздние постоянные позиции','Средняя позиция в конце'],[
        [r['config']['name'],str(r['unique_pairs']),f"{r['late_unchanged_opinions']}/{r['late_agent_steps']}",f"{r['rounds'][-1]['mean_opinion']:.4f}"] for r in bonsai['runs']
    ],[.36,.15,.24,.25])
    p(s,'Основное условие rotating_text сравнивается с постоянными парами fixed_text; без собственной аргументации rotating_no_own; с числами соседей rotating_numeric; с названиями ролей вместо подробных потребностей rotating_role_only. В каждом сравнении меняется один указанный фактор. Первый раунд пар одинаков в основном и фиксированном условиях.')
    p(s,'Постоянные пары используют 3 уникальные связи, сменные - 15. Связи и адресная доставка проверены тестами. Seed 41 фиксирует одну перестановку профилей и порядок встреч. Порядок выполнения условий не рандомизирован. Повторов генерации и нескольких перестановок в этой серии нет.')
    p(s,'В этой серии численные траектории rotating_text, fixed_text и rotating_numeric совпали полностью. Без собственной истории в раунде 3 дополнительно сменили сторону пенсионер и библиотекарь; с одной ролью все шесть участников оставались на -1. Это чувствительность одной конфигурации, а не общая оценка пользы памяти или смены пар.')
    h(s,'Нерелевантная новость')
    p(s,'В общем обсуждении одновременно меняются собеседник и доступная собственная история. Поэтому движение в раунде с фасадом нельзя автоматически приписать фасаду. Для этого есть отдельная парная диагностика без собеседников.')
    p(s,'Разность позиций между свежими одношаговыми ответами с нерелевантным фактом и без него, по шести профилям: bonsai '+', '.join(f'{x:+.3f}' for x in diag_b['paired_irrelevant_opinion_changes'])+'; Luna '+', '.join(f'{x:+.3f}' for x in diag_l['paired_irrelevant_opinion_changes'])+'.')
    p(s,'Это не последовательное обновление одного агента. В диагностике позиция формируется заново; у Codex не зафиксирована температура. Для отделения чувствительности к новости от вариации генерации нужны повторные базовые ответы.')
    p(s,'Статистическая значимость не оценивается. Правдоподобная персональная причина сохранения позиции допустима. Постоянство позиции само по себе не означает провал, как и её изменение само по себе не означает понимание.')

    s=page('Противоречия и содержательная проверка')
    p(s,'Выборочно просмотрены исходные ответы. Это проверка автора анализа по явно заданным фактам, а не независимая экспертная разметка всех реплик. Контрпримеры сохранены с точными цитатами в artifacts/analysis/deliberation_manual_review_2026-11-25.json.')
    h(s,'bonsai: факты извлечены, но довод им противоречит')
    p(s,'Студент, раунд 2: цифровая стоимость в beliefs равна 120, бюджет профиля 100, но текст утверждает, что стоимость укладывается в 100. Пенсионер и библиотекарь, раунд 3: beliefs верно содержат digital=40 и printed=80, но тексты называют печатный вариант более дешёвым. Проверка только JSON пропустила бы эти ошибки.')
    p(s,'Пенсионер, раунд 5, объясняет выбор временем чтения с детьми. Такого обстоятельства в его профиле нет; оно задано родителю. Это неподтверждённая личная деталь, а не факт о настоящем человеке.')
    h(s,'Как использовать сравнение с Luna')
    p(s,'В просмотренных репликах Luna студент сохраняет печатный вариант при цифровой стоимости 120 и бюджете 100, выбирает цифровой при 40 и возвращается к печатному после исправления до 140. Библиотекарь сохраняет печатный вариант, но явно признаёт цифровой более дешёвым при 40 против 80. Эти четыре положительных примера также сохранены с точными цитатами; все реплики независимо не размечались.')
    p(s,'Один корректный арифметический ответ Luna (-0,04), 24 диагностических случая и один сценарий не доказывают общего превосходства модели. Полученные контрпримеры уже достаточны, чтобы не считать правильные beliefs подтверждением качества свободного обсуждения.')
    h(s,'Следующий исследовательский шаг')
    p(s,'Составить независимую разметку противоречий и персональных доводов; повторить несколько перестановок профилей и порядок событий. Для чистого сравнения моделей использовать одинаковый прямой API, схему, системную инструкцию и параметры. Для эффекта смены пар повторять основной и фиксированный протоколы попарно.')

    s=page('Интеграция, расход и воспроизведение')
    h(s,'Что получилось с GPT-Luna через Codex')
    p(s,'Работает Codex CLI 0.171.0-alpha.13.2 с запрошенной gpt-6-luna: арифметическая проба, короткий запуск и основной сценарий Concordia. CodexModel реализует LanguageModel; каждый вызов отдельный, ephemeral, read-only, со схемой ответа и проверкой отсутствия инструментов. Авторизация используется на месте и не извлекается.')
    table(s,['Основная серия','Вызовы','Входные токены','Выходные токены'],[
        ['bonsai / API',str(bonsai['calls']),str(bonsai['usage']['input_tokens']),str(bonsai['usage']['output_tokens'])],
        ['Luna / Codex',str(luna['calls']),str(luna['usage']['input_tokens']),str(luna['usage']['output_tokens'])]
    ],[.34,.16,.25,.25])
    p(s,'Токены указаны по usage каждого маршрута. Вход Codex включает большой служебный контекст. CLI-вызовы и HTTP-запросы не эквивалентны по серверной работе или стоимости. Денежная цена и остаток квоты не установлены. Smoke и исправленная диагностика не включены в эту таблицу; их расход сохранён отдельно в итоговом JSON.')
    p(s,f"С учётом всех новых проб и исправлений: {all_usage['new_bonsai_http_calls']} HTTP-вызов bonsai, 280 436 токенов; {all_usage['new_codex_cli_invocations']} CLI-вызовов Codex, 1 572 620 токенов по usage. Входные токены Codex включают 894 464 кэшированных; это часть входа, а не дополнительный расход поверх общей суммы.")
    h(s,'Сложности и исправления')
    p(s,'Первый bonsai smoke остановился на слишком длинном reason (421 вместо запрошенных 350 символов). Ответ сохранён; в новой серии краткость оценивается отдельно, а не отбрасывает содержательный ответ. В раннем одношаговом диагностическом контексте был несогласованный номер текущего раунда; для обоих маршрутов диагностика отдельно повторена с общей временной отметкой 4. Основные пятираундовые симуляции этим дефектом не затронуты.')
    p(s,'Смена пар - 2/5 по инженерной сложности, сборка памяти и CLI - 3/5, интерпретация текста - 4/5. Человеко-часы не измерялись. Основные ограничения: одна перестановка, один сценарий, неполное сравнение абляций второй модели, разные маршруты и выборочная разметка.')
    h(s,'Что показать и где смотреть')
    p(s,'Открыть demo/discussion.html локально: переключить модель, раунд и участника, показать смену трёх пар, конкретное новое сведение, аргумент и факты. Страница автономна и не вызывает модели. Протокол: docs/DELIBERATION_V2.md. Скрипты: run_deliberation.py, analyze_deliberation.py, build_discussion_demo.py.')
    p(s,'Второй ключ сейчас не нужен для маршрута Codex. При необходимости отдельный бесплатный API: openrouter.ai/settings/keys и конкретная модель :free из каталога; действуют квоты и доступность. Шаблон .env.compare.example; реальный .env.compare исключён из Git. Не использовать случайную маршрутизацию openrouter/free для фиксированного сравнения.')
    render_report(pages,ROOT/'reports','deliberation_v2_report','Новые собеседники и проверяемые факты',
        'Коллективные предпочтения | Второй протокол | 25.11.2026')
    print(json.dumps({'pages':len(PdfReader(ROOT/'reports/deliberation_v2_report.pdf').pages),'new_model_calls':0}))


if __name__=='__main__':main()
